import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
import {issueCredential,verifyCredential} from '../src/modules/auth/credentials.js';
import {hashToken} from '../src/http/middleware/auth.js';
async function fixture(fn) {
  const s=await testServer();
  try {
    const owner=s.agent(),member=s.agent(),other=s.agent();
    const signup=async(agent,name)=>{const result=await agent('POST','/auth/signup',{name,email:name+'@crew.test',password:'correct horse battery'});assert.equal(result.status,201);return result.data.user;};
    const user=await signup(owner,'owner'),recipient=await signup(member,'recipient'),outsider=await signup(other,'outsider');
    const org=(await owner('POST','/orgs',{name:'Security Team'})).data.organization;
    const project=(await owner('POST','/orgs/'+org.id+'/projects',{key:'SEC',name:'Security project'})).data.project;
    const invite=async(body={})=>owner('POST','/orgs/'+org.id+'/invitations',{email:recipient.email,role:'member',...body});
    const linkToken=async(agent,kind='invite')=>{
      const response=await agent('GET','/me/outbox?kind='+kind);assert.equal(response.status,200);
      return new URL(response.data.items[0].payload.link).hash.split('token=')[1];
    };
    await fn({s,owner,member,other,user,recipient,outsider,org,project,invite,linkToken});
  }finally{await s.close();}
}
const cases={
  'signed credentials are purpose bound and reject tampering or changed secret':async()=>{
    const token=issueCredential('first','session');assert(verifyCredential('first','session',token));
    assert(!verifyCredential('second','session',token));assert(!verifyCredential('first','api',token));
    assert(!verifyCredential('first','session',token.slice(0,-2)+'zz'));assert(!verifyCredential('first','session','random'));
  },
  'invitation outbox contains signed link while invitation persists hash only':async({s,invite,member,linkToken,org})=>{
    const created=await invite();assert.equal(created.status,201);assert.equal(created.data.invitation.role,'member');
    const token=decodeURIComponent(await linkToken(member));
    const stored=s.ctx.db.prepare('SELECT * FROM invitations WHERE id=?').get(created.data.invitation.id);
    assert.equal(stored.token_hash,hashToken(token));assert(!JSON.stringify(stored).includes(token));
    assert(!JSON.stringify(created.data).includes(token));
    const outbox=await member('GET','/me/outbox?kind=invite');assert.equal(outbox.data.items[0].orgId,org.id);
  },
  'invitation acceptance grants exact membership and one-use replay fails':async({owner,member,recipient,invite,linkToken,org})=>{
    await invite({role:'admin'});const token=decodeURIComponent(await linkToken(member));
    const accepted=await member('POST','/invitations/accept',{token});assert.equal(accepted.status,200);assert.equal(accepted.data.membership.role,'admin');
    assert.equal((await member('POST','/invitations/accept',{token})).status,409);
    const members=(await owner('GET','/orgs/'+org.id+'/members')).data.items;assert.equal(members.find(m=>m.userId===recipient.id).role,'admin');
  },
  'invitation recipient cannot be substituted':async({other,invite,member,linkToken})=>{
    await invite();const token=decodeURIComponent(await linkToken(member));assert.equal((await other('POST','/invitations/accept',{token})).status,403);
    assert.equal((await member('POST','/invitations/accept',{token})).status,200);
  },
  'revocation makes the invitation link immediately unusable':async({owner,invite,member,linkToken})=>{
    const invitation=(await invite()).data.invitation;const token=decodeURIComponent(await linkToken(member));
    const revoked=await owner('DELETE','/invitations/'+invitation.id);assert.equal(revoked.data.invitation.state,'revoked');
    assert.equal((await member('POST','/invitations/accept',{token})).status,409);
    assert.equal((await owner('DELETE','/invitations/'+invitation.id)).status,409);
  },
  'expired invitation rejects preview and acceptance':async({s,invite,member,linkToken})=>{
    const invitation=(await invite()).data.invitation;const token=decodeURIComponent(await linkToken(member));
    s.ctx.db.prepare('UPDATE invitations SET expires_at=? WHERE id=?').run('2000-01-01T00:00:00.000Z',invitation.id);
    assert.equal((await member('POST','/invitations/preview',{token})).status,409);
    assert.equal((await member('POST','/invitations/accept',{token})).status,409);
  },
  'guest invitation grants only selected projects and lists filter before pagination':async({owner,member,invite,linkToken,org,project})=>{
    const second=(await owner('POST','/orgs/'+org.id+'/projects',{key:'HIDE',name:'Hidden'})).data.project;
    await invite({role:'guest',projectIds:[project.id]});const token=decodeURIComponent(await linkToken(member));
    await member('POST','/invitations/accept',{token});
    const list=await member('GET','/orgs/'+org.id+'/projects?limit=1');assert.deepEqual(list.data.items.map(p=>p.id),[project.id]);assert.equal(list.data.nextCursor,null);
    assert.equal((await member('GET','/projects/'+second.id)).status,403);
    assert.equal((await member('POST','/projects/'+project.id+'/issues',{title:'Cannot edit'})).status,403);
  },
  'cross organization project grants and non-guest grants are rejected':async({owner,invite,project})=>{
    assert.equal((await invite({role:'member',projectIds:[project.id]})).status,422);
    const org=(await owner('POST','/orgs',{name:'Other org'})).data.organization;
    const external=(await owner('POST','/orgs/'+org.id+'/projects',{key:'EXT',name:'External'})).data.project;
    assert.equal((await invite({role:'guest',projectIds:[external.id]})).status,422);
  },
  'pending duplicates and already-member invitations preserve existing role':async({invite,owner,org,recipient,member,linkToken})=>{
    await invite();assert.equal((await invite({role:'guest'})).status,409);
    await member('POST','/invitations/accept',{token:decodeURIComponent(await linkToken(member))});
    assert.equal((await invite({role:'owner'})).status,409);
    assert.equal((await owner('GET','/orgs/'+org.id+'/members')).data.items.find(m=>m.userId===recipient.id).role,'member');
  },
  'only owners invite owner role and members cannot administer invitations or outbox':async({owner,member,recipient,org})=>{
    await owner('POST','/orgs/'+org.id+'/members',{userId:recipient.id,role:'admin'});
    assert.equal((await member('POST','/orgs/'+org.id+'/invitations',{email:'new@crew.test',role:'owner'})).status,403);
    await owner('PATCH','/orgs/'+org.id+'/members/'+recipient.id,{role:'member'});
    for(const path of ['/orgs/'+org.id+'/invitations','/orgs/'+org.id+'/outbox'])assert.equal((await member('GET',path)).status,403);
  },
  'invitation preview validates bearer link and list state filters return persisted values':async({owner,invite,member,linkToken,org})=>{
    const created=await invite();const token=decodeURIComponent(await linkToken(member));
    const preview=await member('POST','/invitations/preview',{token});assert.equal(preview.data.invitation.organizationName,'Security Team');
    assert.equal((await member('POST','/invitations/preview',{token:token+'x'})).status,404);
    const listed=await owner('GET','/orgs/'+org.id+'/invitations?state=pending');assert.equal(listed.data.items[0].id,created.data.invitation.id);
    assert.equal((await owner('GET','/orgs/'+org.id+'/invitations?state=bad')).status,422);
  },
  'sessions list contains metadata without credential hashes and revoke ends current session':async({owner})=>{
    const list=await owner('GET','/auth/sessions');const current=list.data.items.find(s=>s.current);assert(current);assert(current.lastUsedAt);
    assert(!JSON.stringify(list.data).includes('token_hash'));
    assert.equal((await owner('DELETE','/auth/sessions/'+current.id)).data.current,true);
    assert.equal((await owner('GET','/me')).status,401);
  },
  'account cannot list or revoke another user session':async({owner,member})=>{
    const current=(await owner('GET','/auth/sessions')).data.items[0];assert.equal((await member('DELETE','/auth/sessions/'+current.id)).status,404);
    assert.equal((await owner('GET','/me')).status,200);
  },
  'revoke other sessions leaves caller live and rejects other browser':async({s,owner,user})=>{
    const second=s.agent();await second('POST','/auth/login',{email:user.email,password:'correct horse battery'});
    assert.equal((await owner('POST','/auth/sessions/revoke-others',{})).data.revoked,1);
    assert.equal((await second('GET','/me')).status,401);assert.equal((await owner('GET','/me')).status,200);
  },
  'password change verifies existing secret retains caller and revokes other sessions':async({s,owner,user})=>{
    const second=s.agent();await second('POST','/auth/login',{email:user.email,password:'correct horse battery'});
    const wrong=await owner('POST','/auth/password/change',{currentPassword:'incorrect',password:'different long password'});assert.equal(wrong.status,422);assert(wrong.data.error.details.currentPassword);
    const changed=await owner('POST','/auth/password/change',{currentPassword:'correct horse battery',password:'different long password'});assert.equal(changed.data.ok,true);
    assert.equal((await second('GET','/me')).status,401);assert.equal((await owner('GET','/me')).status,200);
    assert.equal((await second('POST','/auth/login',{email:user.email,password:'correct horse battery'})).status,401);
    assert.equal((await second('POST','/auth/login',{email:user.email,password:'different long password'})).status,200);
  },
  'reset requests return same response for unknown emails and deliver only own outbox':async({owner,member,user})=>{
    const known=await owner('POST','/auth/password/reset/request',{email:user.email});const unknown=await owner('POST','/auth/password/reset/request',{email:'missing@crew.test'});
    assert.equal(known.status,202);assert.deepEqual(known.data,unknown.data);
    assert.equal((await owner('GET','/me/outbox?kind=reset')).data.items.length,1);
    assert.equal((await member('GET','/me/outbox?kind=reset')).data.items.length,0);
  },
  'reset link uses hash and one-use reset invalidates every session':async({s,owner,user,linkToken})=>{
    await owner('POST','/auth/password/reset/request',{email:user.email});const token=decodeURIComponent(await linkToken(owner,'reset'));
    assert.equal(s.ctx.db.prepare('SELECT token_hash FROM password_resets').get().token_hash,hashToken(token));
    assert.equal((await owner('POST','/auth/password/reset',{token,password:'new reset password'})).status,200);
    assert.equal((await owner('GET','/me')).status,401);
    assert.equal((await owner('POST','/auth/password/reset',{token,password:'another reset password'})).status,422);
    assert.equal((await owner('POST','/auth/login',{email:user.email,password:'new reset password'})).status,200);
  },
  'reset request supersedes previous link and expired link cannot change password':async({s,owner,user,linkToken})=>{
    await owner('POST','/auth/password/reset/request',{email:user.email});const first=decodeURIComponent(await linkToken(owner,'reset'));
    await owner('POST','/auth/password/reset/request',{email:user.email});
    assert.equal((await owner('POST','/auth/password/reset',{token:first,password:'new reset password'})).status,422);
    const rows=(await owner('GET','/me/outbox?kind=reset')).data.items;const second=rows.map(r=>decodeURIComponent(r.payload.link.split('token=')[1])).find(t=>t!==first);
    s.ctx.db.prepare('UPDATE password_resets SET expires_at=? WHERE token_hash=?').run('2000-01-01T00:00:00.000Z',hashToken(second));
    assert.equal((await owner('POST','/auth/password/reset',{token:second,password:'new reset password'})).status,422);
  },
  'invitation and account events carry identities without secrets':async({s,owner,invite,member,linkToken,user})=>{
    const events=[];const unsubscribe=s.ctx.bus.subscribe(e=>events.push(e));
    await invite();const token=decodeURIComponent(await linkToken(member));await member('POST','/invitations/accept',{token});
    await owner('POST','/auth/password/reset/request',{email:user.email});unsubscribe();
    assert(events.some(e=>e.action==='accepted'&&e.orgId));
    assert(events.every(e=>e.entityId&&e.actorId&&e.time&&Object.hasOwn(e,'before')&&Object.hasOwn(e,'after')));
    const serialized=JSON.stringify(events);assert(!serialized.includes(token));assert(!serialized.includes('password_hash'));assert(!serialized.includes('scrypt:'));assert(!serialized.includes('/#/reset'));
  }
};
for(const [name,fn] of Object.entries(cases))test(name,()=>fixture(fn));
